// edl.js — the timeline. Shots come from beats.js (generated by beats.py from beats_data.py); scenes from acts/*.js.
// Naming conventions it relies on: a scene name containing 'chap' = step/chapter card, 'card'/'poem' = text card or page
// (they own their camera), 'card_l' = a quoted-text card while it is read (no layout caption).
// A beat whose scene is not built yet renders a storyboard placeholder panel describing it.
SCENES.__board=(t,c)=>{const b=c.a.beat;sky3('#0B1022','#151B33','#0A0D18');stars(t,60,b.id.length*7+3,0,0,W,H,0.5);
 g.save();g.strokeStyle='rgba(255,255,255,0.25)';g.setLineDash([6,6]);g.strokeRect(30,SAFE_TOP+10,W-60,c.split?Math.min(420,H*0.33):Math.min(800,SAFE_BOT-SAFE_TOP-40));g.restore();
 T((b.scene||'')+'  ·  '+b.lay,W/2,SAFE_TOP+50,22,'#9fb4ff',FAM.sans,'700','center',1,{kind:'deco'});
 const words=b.visual.split(' ');let line='',y=SAFE_TOP+110;g.font=F(24,FAM.text);for(const w of words){const tt=line?line+' '+w:w;if(g.measureText(tt).width>W-110){T(line,W/2,y,24,'#e8ecff',FAM.text,'400','center',1,{kind:'deco'});y+=32;line=w}else line=tt}T(line,W/2,y,24,'#e8ecff',FAM.text,'400','center',1,{kind:'deco'});
 T(b.motif?('motif: '+b.motif):'',W/2,y+50,20,'#F2C46B',FAM.sans,'600','center',1,{kind:'deco'})};
// C entries rotate the template's three moves (settle / land / punch-in); cards own their entry; chapter cards push themselves
const C_ENTRY=[{z0:1.3,d:0.38},{z0:0.955,d:0.4,push:0.012},{z0:1.0,z1:1.27,d:0.2,push:0.03}];
function buildEDL(){let ci=0;for(const b of BEATS){const sc=b.scene&&SCENES[b.scene]?b.scene:(b.scene?'__board':null);
  const shot={id:b.id,t0:b.t0,t1:b.t1,lay:b.lay,scene:sc,args:{...(b.args||{}),beat:b,punch:!!b.punch},cap:b.cap,tr:b.tr||'cut',zoom:b.zoom,fy:b.fy,fs:b.fs,fx:b.fx,cam:b.cam==='own'?{z0:1,second:false,push:0}:b.cam};
  shot.key=b.key;const sn=b.scene||'';
  if(!b.cam){if(b.lay==='C')shot.cam=C_ENTRY[(ci++)%3];else if(b.lay==='F'&&/chap/.test(sn))shot.cam={z0:1,second:false,push:0};else if(b.lay==='F'&&/card|poem/.test(sn))shot.cam={z0:1,second:false,push:0}}
  if(b.lay==='F'&&!b.cap)shot.cap=/card_l/.test(sn)?'none':'word';SHOTS.push(shot)}}
